fn is_prime(n: i8) -> bool {
    // Requires: n must be greater than or equal to -128 and less than or equal to 127
    // Ensures: Returns true if n is a prime number, false otherwise
    // Invariant: For all k in the range 2..n, if n % k == 0, then n is not prime
    // Decreases: n (as a natural number)
    // This function is only valid for n >= 0, so we will assert that n is in the valid range.
    assert!(n >= -128 && n <= 127);
    
    if n < 2 {
        return false;
    }

    // Iterate over possible divisors from 2 to n-1
    for k in 2..n {
        // If n is divisible by k, it is not prime
        if n % k == 0 {
            return false;
        }
    }

    // If no divisors were found, n is prime
    true
}

fn main() {
    // Test cases
    println!("{}", is_prime(1));  // false
    println!("{}", is_prime(2));  // true
    println!("{}", is_prime(3));  // true
    println!("{}", is_prime(4));  // false
    println!("{}", is_prime(5));  // true
    println!("{}", is_prime(-1)); // false
    println!("{}", is_prime(-5)); // false
    println!("{}", is_prime(127)); // true
    println!("{}", is_prime(128)); // false
}